 "Where the fields above were read from. Later entries only fill in what earlier ones left blank.": "위 필드를 읽어 온 출처입니다. 뒤의 항목은 앞의 항목이 비워 둔 자리만 채웁니다.",
 "read from {sources}": "{sources}에서 읽음",
 "All header fields ({count})": "전체 헤더 필드 ({count})",
 "No sidecar anywhere beside this file — everything below was read from the file itself.": "이 파일 옆에 사이드카가 전혀 없습니다 — 아래 내용은 모두 파일 자체에서 읽었습니다.",
 "The header could not be read: {error}": "헤더를 읽을 수 없습니다: {error}",
 "Specification": "사양",
 "Dataset tags": "데이터셋 태그",
 "The most frequent words in the training captions — the closest thing this file has to trigger words.": "학습 캡션에서 가장 자주 나온 단어들 — 이 파일에서 트리거 워드에 가장 가까운 정보입니다.",
 "Which folder under models/loras to browse.": "models/loras 아래에서 탐색할 폴더.",
