 "Video": "비디오",
 "Audio": "오디오",
 "Renders": "렌더",
 "Select files to move between folders or delete": "폴더 간 이동 또는 삭제할 파일 선택",
 "Organize": "정리",
 "Open this folder in the file manager of the machine ComfyUI runs on": "이 폴더를 ComfyUI가 실행 중인 머신의 파일 관리자에서 엽니다",
 "Open folder": "폴더 열기",
 "could not open the folder ({status})": "폴더를 열 수 없습니다 ({status})",
 "+  Upload {kind}": "+  {kind} 업로드",
 "All": "전체",
 "New shelf": "새 선반",
 "shelf name": "선반 이름",
 "Shelf names cannot start with a dot.": "선반 이름은 점으로 시작할 수 없습니다.",
 "{name}: {error}": "{name}: {error}",
 "{count} files stayed put — {first}": "파일 {count}개가 이동되지 않았습니다 — {first}",
 "Output folder (root)": "출력 폴더 (루트)",
 "Input folder (root)": "입력 폴더 (루트)",
