 "nobody is cast here yet — pick who says it": "아직 아무도 캐스팅되지 않았습니다 — 말할 사람을 고르세요",
 "Written in the picture": "화면에 보이는 글자",
 "a sign, a banner, a subtitle — the quotes are already the syntax": "간판, 현수막, 자막 — 따옴표 자체가 문법입니다",
 "The language these words are in": "이 대사의 언어",
 "the tag reads [English]": "태그는 [English] 로 적힙니다",
 "the tag reads [{name}]": "태그는 [{name}] 로 적힙니다",
 "How the line is delivered": "대사를 전하는 방식",
 "off-screen, and the lips stay closed — both halves are written for you": "화면 밖에서, 입술은 닫힌 채 — 두 문장 모두 대신 써 줍니다",
 "In this piece": "이 작품 안",
 "in the cast": "캐스트에 있음",
 "All of them, together": "모두 함께",
 "one compound ID over every name — (S1,S2)": "모든 이름을 묶은 복합 ID — (S1,S2)",
 "Cast library": "캐스트 라이브러리",
 "Somebody new": "새로운 사람",
 "Describe a voice": "목소리를 설명하기",
 "age, timbre, pace — they join the cast with no files": "나이, 음색, 말 속도 — 파일 없이 캐스트에 들어갑니다",
 "Who is speaking": "누가 말하는지",
 "a young woman, quiet and breathy": "젊은 여성, 조용하고 숨결 섞인 목소리",
 "They join the cast with no files, and the line is written to them.": "파일 없이 캐스트에 합류하고, 이 대사가 그 사람에게 배정됩니다.",
 "Change this": "이 항목 바꾸기",
 "nobody yet": "아직 없음",
 "back to the line": "대사로 돌아가기",
 "{who} {how} — {language}": "{who} 이(가) {how} — {language}",
 "says": "말한다",
 "asks": "묻는다",
 "replies": "대답한다",
 "whispers": "속삭인다",
 "shouts": "외친다",
 "sings": "노래한다",
 "voiceover": "화면 밖 목소리",
 "The line": "이 대사",
 "change what is said": "무슨 말을 하는지 바꾸기",
 "What is said": "무슨 말을 하는지",
 "Only the words. Who says them, and how, stay as they are.": "말만 바꿉니다. 누가 어떻게 말하는지는 그대로입니다.",
 "take it out of the audio and leave the words on screen": "오디오에서 빼고 글자만 화면에 남깁니다",
 "that job could not be started ({status})": "해당 작업을 시작할 수 없습니다 ({status})",
 "the server queued nothing": "서버가 대기열에 아무것도 넣지 않았습니다",
 "the job finished without an answer": "작업이 결과 없이 끝났습니다",
 "the job failed": "작업이 실패했습니다",
 "cancelled": "취소됨",
 "Waiting for the render…": "렌더가 끝나기를 기다리는 중…",
  "Preview waiting for the render": "미리보기가 렌더를 기다리는 중",
  "The dials still work. This refreshes as soon as the render is done.": "다이얼은 그대로 작동합니다. 렌더가 끝나는 즉시 새로고침됩니다.",
 "This runs once the render ahead of it is done.": "앞선 렌더가 끝나면 실행됩니다.",
 "Stored data": "저장된 데이터",
 "The library": "라이브러리",
 "This browser": "이 브라우저",
 "This machine": "이 컴퓨터",
 "Presets and cast": "프리셋과 출연진",
 "Everything you starred into the preset library. It is stored against your ComfyUI user rather than in a workflow, so it follows you across browsers — and nothing else carries it, which is why it is the half of this page worth reading twice.": "프리셋 라이브러리에 별을 눌러 보관한 모든 것. 워크플로가 아니라 ComfyUI 사용자에 저장되므로 브라우저가 바뀌어도 따라옵니다 — 이것을 옮겨 주는 것은 달리 없으며, 그래서 이 페이지에서 두 번 읽을 가치가 있는 절반입니다.",
 "Pieces": "작품",
 "Whole timelines you saved: the strip, the cast, the weights and the settings that rendered them.": "저장한 타임라인 전체: 스트립, 출연진, 가중치, 그리고 그것을 렌더링한 설정.",
 "Shots": "샷",
 "One card's worth — its prompt, its duration and its seam.": "카드 한 장 분량 — 프롬프트, 길이, 이음매.",
 "Pre-stages": "프리스테이지",
 "A still and the arch that made it.": "스틸 한 장과 그것을 만든 아키텍처.",
 "People you kept, with the files they are built out of and every feature written down about them.": "보관해 둔 인물과, 그 사람을 이루는 파일, 그리고 적어 둔 모든 특징.",
 "Styles": "스타일",
 "A look on its own, without the piece it came off — and the stars on the shipped atlas.": "겉모습만, 그것이 나온 작품과 떼어 놓고 — 그리고 내장 아틀라스에 붙인 별표.",
 "How you left things": "작업하던 상태",
 "What the pack remembers about the way you work, rather than about what you made. Losing any of it costs a few clicks, never a file.": "무엇을 만들었는지가 아니라 어떻게 작업하는지에 대해 이 팩이 기억하는 것. 잃어도 클릭 몇 번의 비용일 뿐, 파일이 사라지지는 않습니다.",
 "Stars and where you left off": "별표와 마지막으로 있던 자리",
 "Starred files, the folder each picker tab opens on, and how large the fullscreen editor draws a take. No file is touched.": "별표한 파일, 피커의 각 탭이 열리는 폴더, 그리고 전체 화면 편집기가 테이크를 그리는 크기. 파일은 건드리지 않습니다.",
 "The LoRA manager's notes": "LoRA 관리자의 기록",
 "Stars, pinned versions, and the strength and trigger words each file was last used at. The LoRAs themselves stay on the disk.": "별표, 고정한 버전, 그리고 각 파일을 마지막으로 쓴 강도와 트리거 단어. LoRA 파일 자체는 디스크에 그대로 남습니다.",
 "Refiner choices": "리파이너 선택",
 "Which model rewrites a prompt, at what temperature, and any template or skill pinned to a family.": "어떤 모델이 프롬프트를 다시 쓰는지, 어느 온도로, 그리고 패밀리에 고정한 템플릿이나 스킬.",
 "Files and settings on this disk": "이 디스크의 파일과 설정",
 "Files on this disk and settings this install renders by. Shared by every workflow that opens here, and by nobody else.": "이 디스크의 파일과 이 설치본이 렌더링에 쓰는 설정. 여기서 여는 모든 워크플로가 공유하며, 그 밖의 누구와도 공유하지 않습니다.",
 "The reference cache": "참조 캐시",
 "Encoded references kept between renders. Deleting them costs the next render one encode each and changes nothing about what it produces.": "렌더링 사이에 보관되는 인코딩된 참조. 지워도 다음 렌더링에서 하나당 한 번 다시 인코딩할 뿐, 결과물은 달라지지 않습니다.",
 "The refiner's server": "리파이너의 서버",
 "The endpoint the remote refiner calls and the key it calls with. The key never leaves this machine, and this is how it goes.": "원격 리파이너가 호출하는 엔드포인트와 그때 쓰는 키. 키는 이 컴퓨터를 떠나지 않으며, 지우려면 여기서 지웁니다.",
 "Every setting on this page": "이 페이지의 모든 설정",
 "Quality, output folders, previews and appearance, back to what the pack ships with.": "품질, 출력 폴더, 미리보기, 모양을 이 팩의 초기 상태로 되돌립니다.",
 "Counting…": "세는 중…",
 "Nothing stored": "저장된 것 없음",
 "Really remove?": "정말 삭제할까요?",
 "Really remove all {count}?": "{count}개 전부 정말 삭제할까요?",
 "Removing…": "삭제 중…",
